const raw = $json.message?.content;
let parsed;
try { parsed = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { return [{ json: { valid: false, errors: ['PRD parse failed: ' + e.message], prdMarkdown: '' } }]; }
const md = String(parsed?.markdown || '');
const errors = [];
if (!md.startsWith('# PRD:')) errors.push('First line must start with "# PRD:"');
const fnv1a = (s) => { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = (h * 0x01000193) >>> 0; } return ('0000000' + h.toString(16)).slice(-8); };
return [{ json: { valid: errors.length === 0, errors, prdMarkdown: md, prdHash: fnv1a(md) } }];

const ctx = $('Pass Context').first().json;
const prdMd = $('Validate PRD').first().json.prdMarkdown;
const jobId = ctx.jobId;
const projectSlug = ctx.projectSlug;
const repoDir = '/opt/workspace/software-delivery';
const projectDir = repoDir + '/' + projectSlug + '-docs';
const remote = 'git@github.com:shlapolosa/software-delivery.git';

let sh = 'set -e\n';
sh += 'mkdir -p /opt/workspace\n';
sh += "if [ ! -d '" + repoDir + "/.git' ]; then git clone '" + remote + "' '" + repoDir + "'; fi\n";
sh += "cd '" + repoDir + "'\ngit fetch origin\n";
sh += "git checkout -B '" + projectSlug + "' 'origin/" + projectSlug + "' 2>/dev/null || git checkout -B '" + projectSlug + "'\n";
sh += "mkdir -p '" + projectDir + "/docs'\n";
sh += "cat > '" + projectDir + "/docs/PRD.md' <<'EOF_" + jobId + "'\n" + prdMd + "\nEOF_" + jobId + "\n";
sh += "git add '" + projectSlug + "-docs/docs/PRD.md'\n";
sh += "git commit -m 'Add PRD for " + projectSlug + " (job " + jobId + ")' || true\n";
sh += "git push -u origin '" + projectSlug + "'\n";

return [{ json: { ...ctx, gitScript: sh, prdMarkdown: prdMd } }];

// Project Manager Chat Handler
const agentConfig = {
  name: 'Project Manager',
  shortName: 'project-manager',
  collectionName: 'agent-knowledge-project-manager',
  folder: 'agent-docs/project-manager',
  helpFile: '/data/shared/knowledge/agent-docs/project-manager/help.md'
};

const input = $input.all()[0].json;
const intent = input.intent || 'help';
const query = input.query || '';

let response = {
  agent: agentConfig.name,
  intent: intent,
  success: true
};

switch (intent) {
  case 'help':
    response.content = `# ${agentConfig.name} Agent Help\n\n## Available Commands\n\n| Intent | Description |\n|--------|-------------|\n| help | Show this help message |\n| status | Check knowledge base status |\n| list | List documents in knowledge base |\n| upload | Upload a document to knowledge base |\n| reload | Reload all documents in knowledge base |\n| query | Query the knowledge base |\n\n## Knowledge Base\n- Collection: ${agentConfig.collectionName}\n- Folder: ${agentConfig.folder}\n\n## PM Domains\n- Product Requirements (PRD)\n- Sprint Planning\n- Resource Management\n- Timeline Estimation\n`;
    response.message = `${agentConfig.name} Help`;
    break;

  case 'status':
    response.action = 'query_qdrant_status';
    response.collection = agentConfig.collectionName;
    break;

  case 'list':
    response.action = 'query_qdrant_list';
    response.collection = agentConfig.collectionName;
    break;

  case 'upload':
    response.action = 'call_knowledge_loader';
    response.loaderPayload = {
      action: 'upload',
      collection: agentConfig.collectionName,
      folder: agentConfig.folder,
      content: input.content || '',
      filename: input.filename || ''
    };
    break;

  case 'reload':
    response.action = 'call_knowledge_loader';
    response.loaderPayload = {
      action: 'reload',
      collection: agentConfig.collectionName,
      folder: agentConfig.folder
    };
    break;

  case 'query':
    response.action = 'rag_query';
    response.collection = agentConfig.collectionName;
    response.query = query;
    break;

  default:
    response.success = false;
    response.errorMessage = `Unknown intent: ${intent}. Valid intents: help, status, list, upload, reload, query`;
}

return [{ json: response }];

// Build Azure DevOps push payload
const ctx = $("Build Git Script").first().json;
const repoInfo = $("Get Azure Repo Info").first().json;
const branchCheck = $json;
const projectSlug = ctx.projectSlug;
const jobId = ctx.jobId;

// Get artifact content
const artifactContent = ctx.artifactContent || ctx.artifactMarkdown || ctx.projectMgmtMarkdown || ctx.content || "";

// Include jobId in filename for uniqueness
const artifactPath = `/docs/project-management-${jobId}.md`;

// Determine branch reference
const branchName = `refs/heads/${projectSlug}`;

// Check if branch exists and get its current commit SHA
let oldObjectId = "0000000000000000000000000000000000000000";

if (branchCheck.value && branchCheck.value.length > 0) {
  oldObjectId = branchCheck.value[0].objectId;
}

// Always use 'add' for new unique filenames (with jobId)
const changeType = "add";

// Build the push payload
const changes = [{
  changeType: changeType,
  item: { path: `/${projectSlug}-docs${artifactPath}` },
  newContent: {
    content: Buffer.from(artifactContent).toString("base64"),
    contentType: "base64encoded"
  }
}];

return [{
  json: {
    ...ctx,
    azurePushPayload: {
      refUpdates: [{
        name: branchName,
        oldObjectId: oldObjectId
      }],
      commits: [{
        comment: `Add project management artifacts for ${projectSlug} (job ${jobId})`,
        changes: changes
      }]
    },
    azureRepoInfo: repoInfo,
    branchExists: branchCheck.value && branchCheck.value.length > 0
  }
}];

